import pymupdf,re
d=pymupdf.open('realplan.pdf')
kw=re.compile(r'REFLECT|CEILING|PLAN|SCHEDULE|LEGEND|ELEVATION|SECTION|DETAIL|INDEX|COVER',re.I)
for i in range(0,31):
    p=d[i]
    ws=p.get_text("words")
    # biggest font words: use spans
    big=[]
    for b in p.get_text("dict")["blocks"]:
        for l in b.get("lines",[]):
            for s in l["spans"]:
                if s["size"]>13 and kw.search(s["text"]):
                    big.append((round(s["size"]),s["text"].strip()[:60]))
    seen=[];out=[]
    for sz,t in big:
        if t not in seen: seen.append(t); out.append(f"{sz}:{t}")
    print(i,'|',' || '.join(out[:6]))
